import sys

def transaction_type(number):
    if not number:
        return "No Output Needed"

    if number < 0:
        sign = "-"
    else:
        sign = ""

    number_str = str(number)
    res = ""
    for char in number_str:
        res = char + res

    if number == 0:
        return f"Transaction Type -> {sign}{number}{res[:len(number_str)]}

if __name__ == "__main__":
    number = int(input())
    transaction_type_str = transaction_type(number)
    print("Transaction Type")
    print("->", transaction_type_str)
